package com.isc.facebiometricservice.videoverification;

import com.isc.facebiometricservice.biometric.FaceMatcher;
import com.isc.facebiometricservice.biometric.ReferenceEmbeddingRepository;
import com.isc.facebiometricservice.config.BiometricProperties;
import com.isc.facebiometricservice.config.VideoVerificationProperties;
import com.isc.facebiometricservice.util.ModelPathResolver;
import ai.onnxruntime.*;
import org.opencv.core.*;
import org.opencv.imgproc.Imgproc;
import org.opencv.objdetect.FaceDetectorYN;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.nio.FloatBuffer;
import java.nio.file.Path;
import java.util.*;

@Service
public class VideoVerificationEngine {
 private static final Logger log=LoggerFactory.getLogger(VideoVerificationEngine.class);
 private final VideoVerificationProperties p; private final BiometricProperties biometric; private final FaceMatcher matcher; private final ReferenceEmbeddingRepository refs; private final FaceDetectorYN detector; private final OrtEnvironment env=OrtEnvironment.getEnvironment(); private final OrtSession recognition,liveness; private static final double[] TARGET={38.2946,51.6963,73.5318,51.5014,56.0252,71.7366};
 public VideoVerificationEngine(VideoVerificationProperties p,BiometricProperties biometric,FaceMatcher matcher,ReferenceEmbeddingRepository refs){this.p=p;this.biometric=biometric;this.matcher=matcher;this.refs=refs;try{Path detectorPath=ModelPathResolver.resolve(p.detectorModelPath());Path recognitionPath=ModelPathResolver.resolve(p.recognitionModelPath());Path livenessPath=ModelPathResolver.resolve(p.livenessModelPath());log.info("Video verification model initialization: detector={}, recognition={}, liveness={}, recognitionDimension={}, threshold={}, livenessRequired={}",detectorPath,recognitionPath,livenessPath,biometric.dimension(),biometric.threshold(),p.livenessRequired());detector=FaceDetectorYN.create(detectorPath.toString(),"",new Size(320,320),.8f,.3f,5000);recognition=session(recognitionPath);liveness=session(livenessPath);log.info("Video verification models initialized successfully");logLivenessContract(liveness,livenessPath);}catch(Exception e){log.error("Video verification model initialization failed",e);throw new IllegalStateException("Video verification models could not be initialized",e);}}
 private OrtSession session(Path path)throws Exception{return env.createSession(path.toString(),new OrtSession.SessionOptions());}
 private void logLivenessContract(OrtSession session,Path path){try{log.info("MiniFASNetV2 contract: modelPath={}, inputs={}, outputs={}",path,session.getInputNames(),session.getOutputNames());for(String n:session.getInputNames()){var i=session.getInputInfo().get(n);log.info("MiniFASNetV2 input: name={}, info={}",n,i);if(i.getInfo() instanceof TensorInfo t)log.info("MiniFASNetV2 input tensor: name={}, shape={}, type={}",n,Arrays.toString(t.getShape()),t.type);}for(String n:session.getOutputNames()){var o=session.getOutputInfo().get(n);log.info("MiniFASNetV2 output: name={}, info={}",n,o);if(o.getInfo() instanceof TensorInfo t)log.info("MiniFASNetV2 output tensor: name={}, shape={}, type={}",n,Arrays.toString(t.getShape()),t.type);}}catch(Exception e){log.warn("MiniFASNetV2 contract inspection failed: modelPath={}",path,e);}}
 public Outcome verify(String requestId,VideoClipDecoder.DecodedClip clip,String referenceId){long start=System.nanoTime();List<Candidate> cands=new ArrayList<>();double liveSum=0;int liveCount=0;log.info("Video verification started: requestId={}, referenceId={}, decodedFrames={}, totalFrames={}, fps={}, durationSeconds={}",requestId,referenceId,clip.frames().size(),clip.totalFrames(),clip.fps(),clip.durationSeconds());try{if(clip.durationSeconds()<p.minDurationSeconds()){log.warn("Video validation failed: requestId={}, reason=INVALID_DURATION, durationSeconds={}, min={}, max={}, fps={}, totalFrames={}",requestId,clip.durationSeconds(),p.minDurationSeconds(),p.maxDurationSeconds(),clip.fps(),clip.totalFrames());return out(requestId,"INCONCLUSIVE",null,0,start,clip,0,"INVALID_VIDEO");}if(clip.durationSeconds()>p.maxDurationSeconds()){log.warn("Video validation failed: requestId={}, reason=VIDEO_TOO_LONG, durationSeconds={}, min={}, max={}",requestId,clip.durationSeconds(),p.minDurationSeconds(),p.maxDurationSeconds());return out(requestId,"INCONCLUSIVE",null,0,start,clip,0,"VIDEO_TOO_LONG");}for(var f:clip.frames()){Detection d=detect(f.image());log.debug("Face detection: requestId={}, frameIndex={}, faces={}",requestId,f.index(),d.count);if(d.count==0)continue;if(d.count>p.maxFaces()){log.warn("Face count validation failed: requestId={}, frameIndex={}, faces={}, maxFaces={}",requestId,f.index(),d.count,p.maxFaces());return out(requestId,"INCONCLUSIVE",null,0,start,clip,0,"MULTIPLE_FACES");}if(d.box.w<p.minFaceSizePixels()||d.box.h<p.minFaceSizePixels()){log.debug("Frame rejected: requestId={}, frameIndex={}, reason=FACE_TOO_SMALL, width={}, height={}, minimum={}",requestId,f.index(),d.box.w,d.box.h,p.minFaceSizePixels());continue;}Quality q=quality(f.image(),d.box);log.debug("Frame quality: requestId={}, frameIndex={}, qualityScore={}, minimum={}",requestId,f.index(),q.score,p.minQualityScore());if(q.score<p.minQualityScore())continue;double ls=liveness(f.image(),d.box,requestId,f.index());liveSum+=ls;liveCount++;log.debug("Frame liveness: requestId={}, frameIndex={}, livenessScore={}, threshold={}",requestId,f.index(),ls,p.livenessThreshold());cands.add(new Candidate(f.index(),f.image(),d,q));}if(cands.isEmpty())return out(requestId,"INCONCLUSIVE",null,0,start,clip,0,"NO_FACE");double live=liveCount==0?0:liveSum/liveCount;log.info("Candidate frames ready: requestId={}, candidates={}, livenessAverage={}, livenessThreshold={}",requestId,cands.size(),live,p.livenessThreshold());if(p.livenessRequired()&&live<p.livenessThreshold())return out(requestId,"INCONCLUSIVE",null,live,start,clip,0,"LIVENESS_FAILED");cands.sort(Comparator.comparingDouble((Candidate x)->x.quality.score).reversed());if(cands.size()>p.recognitionFrames())cands=new ArrayList<>(cands.subList(0,p.recognitionFrames()));log.info("Recognition frames selected: requestId={}, selected={}, aggregation={}",requestId,cands.size(),p.aggregation());var ref=refs.find(referenceId,biometric.modelId(),biometric.modelVersion());if(ref.isEmpty()){log.warn("Reference embedding not found: requestId={}, referenceId={}, modelId={}, modelVersion={}",requestId,referenceId,biometric.modelId(),biometric.modelVersion());return out(requestId,"INCONCLUSIVE",null,live,start,clip,cands.size(),"REFERENCE_NOT_FOUND");}log.info("Reference embedding loaded: requestId={}, referenceId={}, dimension={}, modelId={}, modelVersion={}, normalized={}",requestId,referenceId,ref.get().dimension(),ref.get().modelId(),ref.get().normalized());List<Double> scores=new ArrayList<>();for(Candidate c:cands){float[] probe=embedding(c.image,c.detection);double similarity=matcher.similarity(probe,ref.get().values());scores.add(similarity);log.debug("Cosine comparison: requestId={}, frameIndex={}, similarity={}",requestId,c.frameIndex,similarity);}double score=aggregate(scores,p.aggregation());log.info("Cosine aggregation: requestId={}, scoreCount={}, aggregation={}, similarity={}, threshold={}, decision={}",requestId,scores.size(),p.aggregation(),score,biometric.threshold(),score>=biometric.threshold()?"MATCH":"NO_MATCH");return out(requestId,score>=biometric.threshold()?"MATCH":"NO_MATCH",score,live,start,clip,cands.size(),null);}catch(RuntimeException e){log.error("Video verification failed: requestId={}, referenceId={}",requestId,referenceId,e);throw e;}finally{for(var f:clip.frames())f.image().release();}}
 private Outcome out(String requestId,String r,Double s,double l,long st,VideoClipDecoder.DecodedClip clip,int n,String reason){long ms=elapsed(st);log.info("Video verification completed: requestId={}, result={}, reason={}, similarity={}, livenessScore={}, decodedFrames={}, recognitionFrames={}, processingMs={}",requestId,r,reason,s,l,clip.frames().size(),n,ms);return new Outcome(r,s,l,ms,clip.frames().size(),n,reason==null?List.of():List.of(reason));}
 private Detection detect(Mat image){detector.setInputSize(new Size(image.cols(),image.rows()));Mat faces=new Mat();try{detector.detect(image,faces);int n=faces.rows();if(n==0)return new Detection(0,null);int best=0;float score=-1;for(int i=0;i<n;i++){float[] row=new float[15];faces.get(i,0,row);if(row[14]>score){score=row[14];best=i;}}float[] row=new float[15];faces.get(best,0,row);return new Detection(n,new Box(row[0],row[1],row[2],row[3],row));}finally{faces.release();}}
 private Quality quality(Mat image,Box b){int x=Math.max(0,(int)b.x),y=Math.max(0,(int)b.y),w=Math.min(image.cols()-x,Math.max(1,(int)b.w)),h=Math.min(image.rows()-y,Math.max(1,(int)b.h));Mat crop=new Mat(image,new Rect(x,y,w,h)),gray=new Mat(),lap=new Mat();try{Imgproc.cvtColor(crop,gray,Imgproc.COLOR_BGR2GRAY);MatOfDouble mean=new MatOfDouble(),sd=new MatOfDouble();Core.meanStdDev(gray,mean,sd);Imgproc.Laplacian(gray,lap,CvType.CV_64F);MatOfDouble lm=new MatOfDouble(),ls=new MatOfDouble();Core.meanStdDev(lap,lm,ls);double blur=Math.min(1,ls.get(0,0)[0]*ls.get(0,0)[0]/400.0);double light=1-Math.min(1,Math.abs(mean.get(0,0)[0]-128)/128);double size=Math.min(1,Math.min(b.w/image.cols(),b.h/image.rows())/.18);return new Quality(.45*blur+.35*light+.20*size);}finally{crop.release();gray.release();lap.release();}}
 private double liveness(Mat image,Box b,String requestId,int frameIndex){Mat c=cropLiveness(image,b,80);try{float[] x=livenessTensor(c,80);logTensorDiagnostics(x,requestId,frameIndex);float[] y=run(liveness,x,new long[]{1,3,80,80},"liveness",frameIndex);double[]q=softmax(y);int selected=q.length>1?1:0;double score=q.length>selected?q[selected]:0;log.info("MiniFASNetV2 inference: requestId={}, frameIndex={}, logits={}, probabilities={}, selectedClassIndex={}, selectedClassScore={}",requestId,frameIndex,Arrays.toString(y),Arrays.toString(q),selected,score);return score;}finally{c.release();}}
 private void logTensorDiagnostics(float[] x,String requestId,int frameIndex){float min=Float.POSITIVE_INFINITY,max=Float.NEGATIVE_INFINITY;for(float v:x){if(!Float.isFinite(v)){log.warn("MiniFASNetV2 tensor contains non-finite value: requestId={}, frameIndex={}, value={}",requestId,frameIndex,v);return;}min=Math.min(min,v);max=Math.max(max,v);}log.debug("MiniFASNetV2 tensor: requestId={}, frameIndex={}, shape=[1,3,80,80], elements={}, min={}, max={}, firstValues={}",requestId,frameIndex,x.length,min,max,Arrays.toString(Arrays.copyOf(x,Math.min(12,x.length))));}
 private float[] embedding(Mat image,Detection d){Mat a=align(image,d.box.values);try{return normalize(run(recognition,tensor(a,112),new long[]{1,3,112,112},"recognition",-1));}finally{a.release();}}
 private Mat align(Mat f,float[]v){MatOfPoint2f s=new MatOfPoint2f(new Point(v[4],v[5]),new Point(v[6],v[7]),new Point(v[8],v[9])),t=new MatOfPoint2f(new Point(TARGET[0],TARGET[1]),new Point(TARGET[2],TARGET[3]),new Point(TARGET[4],TARGET[5]));Mat m=Imgproc.getAffineTransform(s,t),o=new Mat();Imgproc.warpAffine(f,o,m,new Size(112,112));s.release();t.release();m.release();return o;}
 private Mat cropLiveness(Mat image,Box b,int size){double requestedScale=2.7;double scale=Math.min(requestedScale,Math.min((image.rows()-1.0)/b.h,(image.cols()-1.0)/b.w));double cx=b.x+b.w/2.0,cy=b.y+b.h/2.0;double w=b.w*scale,h=b.h*scale;double left=cx-w/2.0,top=cy-h/2.0,right=cx+w/2.0,bottom=cy+h/2.0;if(left<0){right-=left;left=0;}if(top<0){bottom-=top;top=0;}if(right>image.cols()-1){left-=right-image.cols()+1;right=image.cols()-1;}if(bottom>image.rows()-1){top-=bottom-image.rows()+1;bottom=image.rows()-1;}int x0=Math.max(0,(int)left),y0=Math.max(0,(int)top),x1=Math.min(image.cols()-1,(int)right),y1=Math.min(image.rows()-1,(int)bottom);int cw=Math.max(1,x1-x0+1),ch=Math.max(1,y1-y0+1);log.debug("Liveness crop: faceX={}, faceY={}, faceWidth={}, faceHeight={}, requestedScale={}, effectiveScale={}, x={}, y={}, width={}, height={}, targetSize={}",b.x,b.y,b.w,b.h,requestedScale,scale,x0,y0,cw,ch,size);Mat c=new Mat(image,new Rect(x0,y0,cw,ch)),o=new Mat();Imgproc.resize(c,o,new Size(size,size));c.release();return o;}
 private float[] livenessTensor(Mat image,int size){Mat f=new Mat();image.convertTo(f,CvType.CV_32FC3,1.0/255.0);float[]hwc=new float[size*size*3];f.get(0,0,hwc);float[]chw=new float[hwc.length];int plane=size*size;for(int y=0;y<size;y++)for(int x=0;x<size;x++){int a=(y*size+x)*3,q=y*size+x;chw[q]=hwc[a];chw[plane+q]=hwc[a+1];chw[2*plane+q]=hwc[a+2];}f.release();return chw;}
 private float[]tensor(Mat image,int size){Mat f=new Mat();image.convertTo(f,CvType.CV_32FC3);float[]hwc=new float[size*size*3];f.get(0,0,hwc);float[]chw=new float[hwc.length];int plane=size*size;for(int y=0;y<size;y++)for(int x=0;x<size;x++){int a=(y*size+x)*3,q=y*size+x;chw[q]=(hwc[a+2]-127.5f)/127.5f;chw[plane+q]=(hwc[a+1]-127.5f)/127.5f;chw[2*plane+q]=(hwc[a]-127.5f)/127.5f;}f.release();return chw;}
 private float[]run(OrtSession s,float[]x,long[]shape,String purpose,int frameIndex){try(OnnxTensor t=OnnxTensor.createTensor(env,FloatBuffer.wrap(x),shape);OrtSession.Result r=s.run(Map.of(s.getInputNames().iterator().next(),t))){Object v=r.get(0).getValue();float[]out=v instanceof float[][]a?a[0]:(float[])v;if("liveness".equals(purpose))log.debug("MiniFASNetV2 raw output: frameIndex={}, output={}",frameIndex,Arrays.toString(out));return out;}catch(Exception e){throw new IllegalStateException("MODEL_ERROR",e);}}
 private float[]normalize(float[]x){double n=0;for(float v:x)n+=v*v;n=Math.sqrt(n);if(n==0)throw new IllegalArgumentException("MODEL_ERROR");float[]o=new float[x.length];for(int i=0;i<x.length;i++)o[i]=(float)(x[i]/n);return o;}
 private double[]softmax(float[]x){double m=-Double.MAX_VALUE;for(float v:x)m=Math.max(m,v);double sum=0;double[]o=new double[x.length];for(int i=0;i<x.length;i++){o[i]=Math.exp(x[i]-m);sum+=o[i];}for(int i=0;i<o.length;i++)o[i]/=sum;return o;}
 private double aggregate(List<Double>s,String mode){if(s.isEmpty())return 0;if("MAX".equalsIgnoreCase(mode))return Collections.max(s);if("MEDIAN".equalsIgnoreCase(mode)){var x=new ArrayList<>(s);Collections.sort(x);return x.get(x.size()/2);}return s.stream().mapToDouble(Double::doubleValue).average().orElse(0);}
 private long elapsed(long n){return(System.nanoTime()-n)/1_000_000;} public record Outcome(String result,Double similarity,Double livenessScore,long processingMs,int decodedFrames,int recognitionFrames,List<String> reasons){} private record Detection(int count,Box box){} private record Box(float x,float y,float w,float h,float[] values){} private record Quality(double score){} private record Candidate(int frameIndex,Mat image,Detection detection,Quality quality){}
}
